// Reset: zero `.bss`, copy `.data` from flash, enable the FPU (CPACR
// CP10 and CP11 full access, then `dsb` and `isb`: the first float
// instruction faults without it), call `main`, trap if it returns.
global_asm!(
    ".section .text.Reset,\"ax\",%progbits",
    ".global Reset",
    ".type Reset,%function",
    ".thumb_func",
    "Reset:",
    "    ldr r0, =_sbss",
    "    ldr r1, =_ebss",
    "    movs r2, #0",
    "0:  cmp r0, r1",
    "    bhs 1f",
    "    stm r0!, {{r2}}",
    "    b 0b",
    "1:  ldr r0, =_sdata",
    "    ldr r1, =_edata",
    "    ldr r2, =_sidata",
    "2:  cmp r0, r1",
    "    bhs 3f",
    "    ldm r2!, {{r3}}",
    "    stm r0!, {{r3}}",
    "    b 2b",
    "3:  ldr r0, =0xE000ED88",
    "    ldr r1, [r0]",
    "    orr r1, r1, #0x00F00000",
    "    str r1, [r0]",
    "    dsb",
    "    isb",
    "    bl main",
    "    udf #0",
    "    .pool",
    ".size Reset, . - Reset",
);

/// Every other exception parks here, distinguishable from the fixed point
/// because the boot word is never written.
unsafe extern "C" fn fault() -> ! {
    loop {
        core::hint::spin_loop();
    }
}

#[unsafe(no_mangle)]
